"""Analiza repeticiones de la misma foto en plan.json: cuantas y a que distancia."""
import json, collections

B = "D:/rtmp/fn09ds"
plan = json.load(open(B + "/plan.json", encoding="utf-8"))
try:
    shots = plan.get("shots") or plan
except AttributeError:
    shots = plan
if isinstance(shots, dict):
    shots = shots.get("plan", [])
print("tipo", type(shots), "n", len(shots))
print("claves", list(shots[0].keys()) if shots else None)

uses = collections.defaultdict(list)
for i, s in enumerate(shots):
    sid = s.get("id") or s.get("img") or s.get("file")
    uses[sid].append((i, s.get("startMs"), s.get("endMs"), s.get("kind") or s.get("tipo")))

foto_uses = {k: v for k, v in uses.items() if k and "avatar" not in str(k).lower() and not str(k).startswith("a")}
rep = {k: v for k, v in foto_uses.items() if len(v) > 1}
print("ids de foto:", len(foto_uses), "· repetidos:", len(rep),
      "· usos extra:", sum(len(v) - 1 for v in rep.values()))
gaps = []
for k, v in rep.items():
    for a, b in zip(v, v[1:]):
        if a[1] is not None and b[1] is not None:
            gaps.append((b[1] - a[1], k, a[1] // 1000, b[1] // 1000))
gaps.sort()
print("repes a <60 s:", sum(1 for g in gaps if g[0] < 60000))
print("repes a <180 s:", sum(1 for g in gaps if g[0] < 180000))
print("repes a >=180 s:", sum(1 for g in gaps if g[0] >= 180000))
for g in gaps[:15]:
    print("  gap %.0fs  %s  %ds -> %ds" % (g[0] / 1000, g[1], g[2], g[3]))

